İşletmeci ONAL YAZILIM OTOMASYON EĞİTİM DANIŞMANLIK SAN. TİC. LTD. ŞTİ., info@onalotomasyon.com, 0505 707 20 05. VPS ve aynı sunucudaki yedekler işletmeci beyanıyla Litvanya'dadır. Google giriş/reCAPTCHA ve Hostinger SMTP kullanılır. Yurt dışı aktarım belgeleri, kesin saklama/imha süreleri ve küçük kullanıcı satın alma kontrolleri tamamlanmamıştır. Test etiketi bu yükümlülükleri kaldırmaz ve katılımcının bu metni kabulü eksik hukuki mekanizmayı tamamlamaz.

Hata/geri bildirimler üçüncü kişi verisi, parola veya erişim anahtarı içermeden destek adresine iletilmelidir. Silme ve veri koruma talepleri KVKK metnindeki usulle yapılabilir. Bu sınırları aşan gerçek eğitim veya ticari satış için ayrı yayın öncesi kontroller tamamlanmalıdır.$legal$);

DO $$ BEGIN
 IF (SELECT count(*) FROM identity."users" WHERE "Email"='admin@eduivme.com') <> 1 THEN
   RAISE EXCEPTION 'Expected existing admin actor not found';
 END IF;
 IF EXISTS (SELECT 1 FROM identity."PlatformLegalPages" p JOIN test_legal_content c ON c.slug=p."Slug" WHERE p."ArchivedAt" IS NOT NULL) THEN
   RAISE EXCEPTION 'Archived document requires explicit restore';
 END IF;
END $$;

INSERT INTO identity."PlatformLegalPageRevisions" ("Id","PageId","Slug","Title","Content","IsPublished","IsArchived","Version","CreatedBy","CreatedAt")
SELECT gen_random_uuid(), p."Id",p."Slug",p."Title",p."Content",p."IsPublished",false,p."Version",coalesce(p."UpdatedBy",p."CreatedBy"),coalesce(p."UpdatedAt",p."CreatedAt")
FROM identity."PlatformLegalPages" p JOIN test_legal_content c ON c.slug=p."Slug"
WHERE p."Content" IS DISTINCT FROM c.content OR p."Title" IS DISTINCT FROM c.title OR NOT p."IsPublished";

INSERT INTO identity."PlatformLegalPages" ("Id","Slug","Title","Content","IsPublished","Version","CreatedBy","CreatedAt")
SELECT gen_random_uuid(),c.slug,c.title,c.content,true,1,u."Id",now()
FROM test_legal_content c CROSS JOIN identity."users" u WHERE u."Email"='admin@eduivme.com'
ON CONFLICT ("Slug") DO UPDATE SET "Title"=excluded."Title", "Content"=excluded."Content", "IsPublished"=true,
 "Version"=identity."PlatformLegalPages"."Version"+1,"UpdatedBy"=excluded."CreatedBy","UpdatedAt"=now()
WHERE identity."PlatformLegalPages"."Content" IS DISTINCT FROM excluded."Content" OR identity."PlatformLegalPages"."Title" IS DISTINCT FROM excluded."Title" OR NOT identity."PlatformLegalPages"."IsPublished";
SELECT "Slug","Version","IsPublished" FROM identity."PlatformLegalPages" WHERE "Slug" IN (SELECT slug FROM test_legal_content) ORDER BY "Slug";
COMMIT;


